import { Block, type MarginStyles, Text } from "@prototyp/skeletor";
import { NavigationContainerRef } from "modules/navigation/const";
import type { FC } from "react";
import { Image, StyleSheet } from "react-native";
import { Button } from "../button";

interface GoBackHeaderProps {
  title?: string;
  margins?: MarginStyles;
  rightComp?: React.ReactNode;
  isClose?: boolean;
  onGoBack?: () => void;
}

export const GoBackHeader: FC<GoBackHeaderProps> = ({
  title,
  margins = [40, 0],
  rightComp,
  isClose,
  onGoBack,
}) => {
  return (
    <Block
      height={24}
      justify="space-between"
      align="center"
      flexDirection="row"
      width="100%"
      margins={margins}
    >
      <Button.Wrapper
        onPress={onGoBack ? onGoBack : () => NavigationContainerRef.goBack()}
        style={styles.button}
      >
        <Block
          flex={1}
          flexDirection="row"
          justify="center"
          align="center"
          gap={12}
        >
          {isClose ? (
            <Image source={require("assets/icons/close.png")} />
          ) : (
            <>
              <Image source={require("assets/icons/caret-left.png")} />
              <Text font="InstrumentSans-Medium">Back</Text>
            </>
          )}
        </Block>
      </Button.Wrapper>
      {title && (
        <Text flex={1} textAlign="center">
          {title}
        </Text>
      )}
      <Block width="20%" align="flex-end">
        {rightComp}
      </Block>
    </Block>
  );
};

const styles = StyleSheet.create({
  button: {
    width: "20%",
    alignItems: "flex-start",
    marginRight: "auto",
  },
});

