interface SecureRoomItemProps {
  room: RoomInterface;
}

export const SecureRoomItem: FC<SecureRoomItemProps> = ({ room }) => {
  const [roomInfo, setRoomInfo] = useState<RoomInfo | null>(null);

  useEffect(() => {
    room.roomInfo().then(setRoomInfo).catch(() => {});
  }, [room]);

  const unread = roomInfo?.numUnreadNotifications ?? 0;

  return (
