const subscribeToRoomList = async () => {
  const syncService = SecondaryMatrixService.syncService;
  if (!syncService) return;

  try {
    const roomListService = syncService.roomListService();
    if (!roomListService) return;

    const roomList = await roomListService.allRooms();

    // Store in ref to prevent GC — dropping this object drops the onUpdate callback
    entriesResultRef.current = roomList.entriesWithDynamicAdaptersWith(
      500,
      true,
      { onUpdate: (updates) => applyDiffs(updates) },
    );

    streamHandleRef.current = entriesResultRef.current.entriesStream();

    // Fallback: when sync reaches Running state, refresh directly from the
    // client in case the stream missed the initial batch of rooms
    stateHandleRef.current = roomListService.state({
      onUpdate: (state: RoomListServiceState) => {
        if (state !== RoomListServiceState.Running) return;

        const instance = SecondaryMatrixService.instance;
        if (!instance) return;

        const filtered = instance.rooms().filter((room) => {
          const m = room.membership();
          return (
            m !== Membership.Banned &&
            m !== Membership.Left &&
            m !== Membership.Knocked
          );
        });

        roomsRef.current = filtered;
        setRooms([...filtered]);
      },
    });
  } catch (error) {
    console.warn("[SecureScreen] Failed to subscribe to room list:", error);
  }
};

