  if (!SecondaryMatrixStorage.has()) {
    setMode("login");
    return;
  }

  const restored = await SecondaryMatrixService.restoreSession();
  if (!restored) {
    setMode("login");
    return;
  }

  await SecondaryMatrixService.startSync();
  await subscribeToRoomList();
  setMode("rooms");
};

toolUseResult.newString:
const init = async () => {
  if (!SecondaryMatrixStorage.has()) {
    setMode("login");
    return;
  }

  // Already active (navigated back without logging out) — skip restoreSession,
  // just restart sync and re-subscribe.
  if (SecondaryMatrixService.instance && SecondaryMatrixService.syncService) {
    await SecondaryMatrixService.startSync();
    await subscribeToRoomList();
    setMode("rooms");
    return;
  }

  const restored = await SecondaryMatrixService.restoreSession();
  if (!restored) {
    setMode("login");
    return;
  }

  await SecondaryMatrixService.startSync();
  await subscribeToRoomList();
  setMode("rooms");
};
